def find_max_subsequence_length(A, D):
    N = len(A)
    if N == 0:
        return 0

    dp = [1] * N
    for i in range(N):
        for j in range(i):
            if abs(A[i] - A[j]) <= D:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

